+// Scratch-only probe controls. These are not original-case observations.
+#[test]
+fn timeout_stdout_restores_flags_after_available_data_without_eof() {
+    let (reader, mut writer) = std::io::pipe().unwrap();
+    let before = rustix::fs::fcntl_getfl(&reader).unwrap();
+    assert!(!before.contains(rustix::fs::OFlags::NONBLOCK));
+    writer.write_all(b"old-updater\n").unwrap();
+    let started = Instant::now();
+    let (saved, sampled, restored) = stdout_now(&reader, started).unwrap();
+    let (during, interval, read) = sampled.unwrap();
+    assert_eq!(saved, before);
+    assert!(during.contains(rustix::fs::OFlags::NONBLOCK));
+    assert_eq!(read.unwrap(), b"old-updater\n");
+    assert_eq!(restored.unwrap(), before);
+    assert_eq!(rustix::fs::fcntl_getfl(&reader).unwrap(), before);
+    eprintln!("probe data control: before={saved:?} during={during:?} interval={interval:?} restored={before:?}");
+    // Keep the writer open through the probe: success did not wait for EOF.
+    drop(writer);
+}
+
+#[test]
+fn timeout_stdout_restores_flags_after_would_block_without_eof() {
+    let (reader, writer) = std::io::pipe().unwrap();
+    let before = rustix::fs::fcntl_getfl(&reader).unwrap();
+    assert!(!before.contains(rustix::fs::OFlags::NONBLOCK));
+    let started = Instant::now();
+    let (saved, sampled, restored) = stdout_now(&reader, started).unwrap();
+    let (during, interval, read) = sampled.unwrap();
+    assert_eq!(saved, before);
+    assert!(during.contains(rustix::fs::OFlags::NONBLOCK));
+    assert_eq!(read.unwrap_err(), rustix::io::Errno::AGAIN);
+    assert_eq!(restored.unwrap(), before);
+    assert_eq!(rustix::fs::fcntl_getfl(&reader).unwrap(), before);
+    eprintln!("probe WouldBlock control: before={saved:?} during={during:?} interval={interval:?} restored={before:?}");
+    // A live empty pipe must not wait for its writer to close.
+    drop(writer);
+}
